// Which parts are fine, from the three checks above. Each check keeps going when it fails (its output then holds the
// error), so this step always runs and every part is reported.
const s = $('Settings').first().json;
for (const [name, value] of Object.entries(s)) {
  if (!String(value ?? '').trim() || String(value).startsWith('PASTE_')) {
    throw new Error(`Settings: ${name} is not filled in. Nothing was checked.`);
  }
}
const short = (t) => String(t ?? '').replace(/\s+/g, ' ').trim().slice(0, 200);
const result = (step) => {
  const r = $(step).first().json;
  if (r.error) return { status: 0, body: null, error: short(r.error.message ?? r.error) };
  return { status: r.statusCode, body: r.body, error: '' };
};
const why = (r) => r.error || `answered ${r.status}`;
const agent = result('Check agent');
const tunnel = result('Check tunnel');
const openai = result('Check OpenAI');
const openaiCode = openai.body?.error?.code ?? openai.body?.error?.type ?? '';
const parts = [
  { part: 'agent', ok: agent.status === 200 && agent.body?.ok === true, detail: why(agent) },
  { part: 'tunnel', ok: tunnel.status === 200, detail: why(tunnel) },
  { part: 'openai', ok: openai.status === 200, detail: openaiCode ? `${openai.status} ${short(openaiCode)}` : why(openai) },
];
for (const p of parts) if (p.ok) p.detail = null;
const failing = parts.filter((p) => !p.ok);
return [{ json: {
  parts,
  all_ok: failing.length === 0,
  summary: failing.length ? failing.map((p) => `${p.part}: ${p.detail}`).join('; ') : 'all well',
} }];

parameters.query:
-- Each part's result goes to monitor_report(), which answers only on a change: "down" when a part just failed,
-- "back" when it just recovered. No row back: nothing changed, so nothing is posted.
select p.part, r.change, r.down_since, extract(epoch from r.down_for)::int as down_seconds, p.detail
from json_to_recordset($1::json) as p(part text, ok boolean, detail text)
cross join lateral monitor_report(p.part, p.ok, p.detail) as r;

parameters.jsCode:
// One Slack message per change: monitor_report answered "down" (just failed) or "back" (just recovered). Nothing
// posts while a part stays down or stays fine, so this never repeats every 5 minutes.
const esc = (t) => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const at = (t) => DateTime.fromJSDate(new Date(t)).setZone($now.zone).toFormat('HH:mm ZZZZ'); // n8n's time zone (New York), named
const mins = (sec) => {
  const m = Math.max(1, Math.round(Number(sec ?? 0) / 60));
  return m < 120 ? `${m} min` : `${Math.round(m / 60)} h`;
};
const DOWN = {
  agent: 'The agent is down',
  tunnel: "Slack can't reach n8n (the Cloudflare tunnel or the public address)",
  openai: "OpenAI isn't answering",
};
const EFFECT = {
  agent: 'New tickets get an "agent unavailable" card until it is back.',
  tunnel: "Client messages may not become tickets until it is back.",
  openai: 'Drafts fail until it is back.',
};
const BACK = { agent: 'The agent is back', tunnel: 'Slack reaches n8n again', openai: 'OpenAI answers again' };
const SPENDING = /spend_limit|credit_balance|insufficient_quota/;

return $input.all().map(({ json: r }) => {
  let text;
  if (r.change === 'back') {
    text = `:large_green_circle: *${BACK[r.part] ?? r.part}* after ${mins(r.down_seconds)} (down since ${at(r.down_since)}).`;
  } else if (r.part === 'openai' && SPENDING.test(r.detail ?? '')) {
    text = `:red_circle: *OpenAI refuses AI calls: the spending limit or the prepaid credit ran out* (${esc(r.detail)}), `
      + `since ${at(r.down_since)}. No drafts until it is raised: platform.openai.com, your OpenAI project, `
      + 'Limits (or Billing for credit).';
  } else {
    text = `:red_circle: *${DOWN[r.part] ?? r.part}* since ${at(r.down_since)}: ${esc(r.detail)}. ${EFFECT[r.part] ?? ''}`;
  }
  return { json: { text } };
});
